// Freeze the configuration: later edits by the caller must not change what this verifier enforces. Each root is copied
// shallowly (its verifier stays the caller's object: behaviour, not data).
policy = Object.freeze({ threshold: policy?.threshold, roots: Array.isArray(policy?.roots) ? Object.freeze(policy.roots.map((r) => (r !== null && typeof r === 'object' ? Object.freeze({ ...r }) : r))) : policy?.roots }) as MultiRootAttestationPolicy;

// Freeze the configuration (e.g. the `require` list, the attestation trust list): later edits by the caller must not
// change what this guard enforces. Stores and hook objects stay the caller's (behaviour/state, not data).
opts = Object.freeze({
  ...snapshotConfig(opts, { keep: ['budgetStore', 'hooks', 'attestation'] }),
  ...(opts.attestation ? { attestation: snapshotConfig(opts.attestation, { keep: ['nonceStore', 'hardwareVerifier', 'resolveDocument'] }) } : {}),
});
